import mongoose from "mongoose";
import { Schema } from 'mongoose';

const chapterSchema = new Schema({
  id: {
    type: String,
    required: true,
  },
  title: {
    type: String,
    required: true,
  },
  duration: {
    type: String,
  },
  progress: {
    type: Number, 
  }
});

const bookSchema = new Schema({
  bookCover: {
    type: String,
    required: true
    // unique:true,
  },
  bookName: {
    type: String,
    required: true,
    // unique: true,
  },
  bookDescription: {
    type: String,
    required: true,
    // unique:true
  },
  bookAuthor: {
    type: String,
    required: true,
  },
  
  audioBook: {
    type: String,
    // unique:true
  },
  status: {
    type: String,
    enum: ['isCertified', 'notCertified'],
    default: 'notCertified',
    required: true
  },
  likes: {
    type: Number,
  },
  chapters: [chapterSchema], 
  listeners: {
    type: Number,
    default: 0,
  },
  category: {
    type: String,
    required: true,
    
  },
  language: {
    type: String,
    required: true,
  },
},
  { timestamps: true }
);

const Book = mongoose.model('Book', bookSchema);
export default Book;
